package com.tripnest.repository; import com.tripnest.entity.*; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface AccommodationRepository extends JpaRepository<Accommodation,Long>{List<Accommodation> findByActiveTrueOrderByRatingDesc(); Optional<Accommodation> findByIdAndActiveTrue(Long id); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from Accommodation a where a.id=:id and a.active=true") Optional<Accommodation> lockActive(@Param("id") Long id);}
